type Result<T> = { ok: true; value: T } | { ok: false; error: string };

const parse = (raw: string): Result<number> => {
  const n = Number(raw);
  return Number.isNaN(n) ? { ok: false, error: 'NaN' } : { ok: true, value: n };
};

